static int32_t electrical_offset_current_counts(float current_a)
{
  return (g_drv_test.current_amp_per_count > 0.0f)
             ? float_to_scaled_i32(current_a / g_drv_test.current_amp_per_count, 1.0f)
             : 0;
}

