static uint32_t electrical_offset_alignment_bucket_index(uint32_t ramp_ms,
                                                         uint32_t elapsed_ms)
{
  if (ramp_ms == 0u) {
    return 0u;
  }
  const uint32_t bucket = electrical_offset_alignment_bucket_index(ramp_ms,
                                                                   elapsed_ms);
  return bucket;
}

