      drv8301_read_registers(&g_drv1, &g_drv_test.drv1_regs);
  g_drv_test.actual_control2_drv0 = g_drv_test.drv0_regs.control2;
  g_drv_test.actual_control2_drv1 = g_drv_test.drv1_regs.control2;
